/**
 * Bundled observation tooltip fallback (Issue #521).
 *
 * A snapshot generated by GRQ embeds `src/v/Tooltips.json` as
 * `snapshot.tooltips`, and that embedded map is always the source of truth so
 * the viewer works for non-GRQ networks. Older snapshots predate the
 * embedding: for those, this module lazily fetches the copy of GRQ's
 * Tooltips.json bundled at `docs/tooltips.json`.
 *
 * The bundle is ~430 KB, so it is fetched on demand rather than precached —
 * a snapshot that carries its own tooltips never pays for it.
 *
 * This module is DOM-free and testable under Deno.
 */

import { extractTooltips } from "./ui_helpers.js";

/** Path of the bundled tooltips file, relative to `docs/shared/`. */
export const FALLBACK_TOOLTIPS_PATH = "../tooltips.json";

/**
 * Resolve the URL of the bundled tooltips file.
 *
 * Resolving against this module's own URL keeps the path correct from both
 * `docs/` (Trace Explorer) and `docs/graph/` (Graph Explorer).
 *
 * @param {string} [base=import.meta.url]
 * @returns {string}
 */
export function fallbackTooltipsUrl(base = import.meta.url) {
  return new URL(FALLBACK_TOOLTIPS_PATH, base).href;
}

/**
 * Decide whether the bundled fallback is needed.
 *
 * @param {{ descriptions?: Record<string, string> }|null|undefined} tooltips —
 *   the result of {@link extractTooltips} for the loaded snapshot.
 * @returns {boolean} true when the snapshot carried no usable descriptions.
 */
export function needsFallbackTooltips(tooltips) {
  const descriptions = tooltips?.descriptions;
  if (!descriptions || typeof descriptions !== "object") return true;
  return Object.keys(descriptions).length === 0;
}

/**
 * Merge a fallback map under a primary map — the primary always wins.
 *
 * @param {Record<string, string>|null|undefined} primary
 * @param {Record<string, string>|null|undefined} fallback
 * @returns {Record<string, string>}
 */
export function mergeTooltipMaps(primary, fallback) {
  return { ...(fallback ?? {}), ...(primary ?? {}) };
}

/** Cached in-flight/settled fetch so the bundle is downloaded at most once. */
let cachedLoad = null;

/** Clear the module-level cache (used by tests). */
export function resetFallbackTooltipsCache() {
  cachedLoad = null;
}

/**
 * Fetch and parse the bundled tooltips file.
 *
 * Fails loudly: a missing or malformed bundle throws rather than resolving to
 * an empty map, so a broken deploy cannot masquerade as "this snapshot simply
 * has no descriptions". A rejected load is not cached, so a later retry can
 * still succeed.
 *
 * @param {{ fetchImpl?: typeof fetch, url?: string }} [opts]
 * @returns {Promise<{ labels: Record<string, string>, descriptions: Record<string, string>, groups: Record<string, string> }>}
 */
export function loadFallbackTooltips(opts = {}) {
  if (cachedLoad) return cachedLoad;

  const fetchImpl = opts.fetchImpl ?? globalThis.fetch;
  const url = opts.url ?? fallbackTooltipsUrl();

  if (typeof fetchImpl !== "function") {
    return Promise.reject(
      new Error("Bundled tooltips: no fetch implementation available"),
    );
  }

  cachedLoad = (async () => {
    const res = await fetchImpl(url);
    if (!res?.ok) {
      throw new Error(
        `Bundled tooltips fetch failed: HTTP ${res?.status ?? "?"} for ${url}`,
      );
    }
    const raw = await res.json();
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
      throw new Error(
        `Bundled tooltips payload is not a uuid-keyed object: ${url}`,
      );
    }
    return extractTooltips({ tooltips: raw });
  })();

  // Drop the cache on failure so a transient error is retryable.
  cachedLoad.catch(() => {
    cachedLoad = null;
  });

  return cachedLoad;
}
